def save_async_checkpoint(step, model_shard, opt_shard, nvme_dir, s3_uploader):
    # 1. Non-blocking HBM -> pinned host CPU copy (~1.5s)
    cpu_state = {
        'step': step,
        'model': {k: v.detach().to('cpu', non_blocking=True) for k, v in model_shard.items()},
        'opt': {k: v.detach().to('cpu', non_blocking=True) for k, v in opt_shard.items()},
    }
    torch.cuda.synchronize()
    # 2. Training resumes immediately; background worker writes NVMe -> S3
    s3_uploader.submit(write_nvme_and_upload, nvme_dir, step, cpu_state)
